        }}
      />
      {file && (
        <ImageCropDialog
          file={file}
          {...dimensions}
          labels={cropLabels}
          onCancel={() => setFile(null)}
          onConfirm={async (cropped) => {
            await onUpload(cropped);
            setFile(null);
          }}
        />
      )}
    </div>
  );
}
